    # Colored centers project their color across their row and column. The
    # vertical projections take precedence at crossings; marker cells persist.
    for r, c, color in sources:
        for j in range(w):
            out[r][j] = color
    for r, c, color in sources:
        for i in range(h):
            out[i][c] = color
    for r, c in markers:
        out[r][c] = 3
    return out

