 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sources = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 3)]
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3}
    centers = {(r, c) for r, c, _ in sources}

    def cast(r, c, color, dr, dc):
        i, j = r, c
        while 0 <= i < h and 0 <= j < w:
            # A ray passes through the cross arms. The source center of another
            # cross blocks it; source colors overwrite at beam intersections.
            if (i, j) in centers and (i, j) != (r, c):
                break
            if (i, j) not in markers:
                out[i][j] = color
            i += dr
            j += dc

    for r, c, color in sources:
        cast(r, c, color, 0, -1)
        cast(r, c, color, 0, 1)
    for r, c, color in sources:
        cast(r, c, color, -1, 0)
        cast(r, c, color, 1, 0)
    for r, c in markers:
        out[r][c] = 3
    return out

if __name__ == '__main__':
    pass
